<?php require_once __DIR__.'/../app/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$parent=(int)($_POST['parent_id']??0)?:null;if($name==='')throw new RuntimeException('Nombre obligatorio.');if($id){db()->prepare('UPDATE categories SET name=?,parent_id=?,icon=?,description=?,active=?,sort_order=? WHERE id=?')->execute([$name,$parent,trim($_POST['icon']??''),trim($_POST['description']??''),isset($_POST['active'])?1:0,(int)($_POST['sort_order']??0),$id]);}else{$slug=slugify($name).'-'.substr(bin2hex(random_bytes(3)),0,4);db()->prepare('INSERT INTO categories(parent_id,name,slug,icon,description,active,sort_order) VALUES(?,?,?,?,?,?,?)')->execute([$parent,$name,$slug,trim($_POST['icon']??''),trim($_POST['description']??''),1,(int)($_POST['sort_order']??0)]);}flash('success','Categoría guardada.');}if($action==='delete'){db()->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Categoría eliminada.');}redirect('../admin/categories.php');}$cats=db()->query('SELECT c.*,p.name parent_name,(SELECT COUNT(*) FROM products pr WHERE pr.category_id=c.id) products FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY c.sort_order,c.name')->fetchAll();$parents=array_filter($cats,fn($c)=>!$c['parent_id']);$adminPage='categories';$adminTitle='Categorías y subcategorías';$adminSubtitle='Organiza el catálogo para que sea fácil encontrar productos';require __DIR__.'/partials/header.php';?>
<div class="admin-grid cols-2"><section class="panel-card mt-0"><div class="panel-head"><div><h2>➕ Crear categoría</h2><p>Puedes crear categorías principales o subcategorías.</p></div></div><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="action" value="save"><div class="form-grid"><label>Nombre<input name="name" required placeholder="Ej: Tecnología"></label><label>Emoji<input name="icon" placeholder="💻"></label><label>Categoría superior<select name="parent_id"><option value="0">Categoría principal</option><?php foreach($parents as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Orden<input type="number" name="sort_order" value="0"></label></div><label class="mt-20">Descripción<textarea name="description" rows="3"></textarea></label><button class="admin-btn mt-20">🗂️ Guardar categoría</button></form></section><section class="panel-card mt-0"><div class="panel-head"><div><h2>📚 Estructura actual</h2><p><?=count($cats)?> categorías y subcategorías</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Categoría</th><th>Superior</th><th>Productos</th><th></th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><b><?=e(($c['icon']?:'📁').' '.$c['name'])?></b><small><?=e($c['description'])?></small></td><td><?=e($c['parent_name']?:'Principal')?></td><td><?=$c['products']?></td><td><?php if(!$c['products']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><button class="admin-btn small danger" name="id" value="<?=$c['id']?>" data-confirm="¿Eliminar esta categoría?">Eliminar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php require __DIR__.'/partials/footer.php';?>
